( SELECT
    DATE(v.hstamp) AS event_date,
    v.channelV2,
    v.publisher_id,
    v.pub_type,
    v.site_id,
    v.site_type,
    v.carrier_id,
    v.country,
    v.region,
    v.city,
    v.zip,
    v.metrocode,
    v.brand,
    v.model,
    v.marketing_name,
    v.os,
    v.os_version,
    v.device_type,
    v.agegroup_id,
    v.gender_id,
    v.house_income_id,
    v.device_lang,
    v.device_browser,
    v.device_browser_version,
    v.path_hop_count,
    v.media_plcmt,
    v.video_maxduration,
    v.is_ias_ip_fraud,
    v.video_skippable,
    v.supports_banner,
    v.supports_video,
    v.supports_richmedia,
    v.supports_native,
    v.supports_vpaid,
    v.ads_txt,
    v.req_authorized,
    v.supports_audio,
    v.audio_skippable,
    v.hhip_flag,
    v.path_complete,
    v.is_private_pmp_deal,
    IFNULL(STRING_AGG(DISTINCT IAB[SAFE_OFFSET(0)], ', ' LIMIT 20), '') AS iab_cats,
    (99 * SUM(avails)) + MOD(SUM(avails), 99) as avails,
    (9100 * APPROX_COUNT_DISTINCT(IF(avails = 100, Coalesce(alias_ip, IF(hhip_flag = 1,ip,NULL)),NULL))) AS hh_uniqs,
    (101 * sum(IF(avails != 100, avails,0))) AS bids,
    (9100 * APPROX_COUNT_DISTINCT(uid)) AS device_uniqs,
    AVG(v.clearing_price) AS min_clearing_price,
    MAX(v.clearing_price) AS max_clearing_price,
    SAFE_DIVIDE(SUM(imps),SUM(bids)) as win_rate,
    (1000 * SAFE_DIVIDE(SUM(spend),SUM(imps))) ecpm
FROM `adelphic-forecasting.ci_event.audience_event_v1` v
${predicate.Builder().CombineOr($predicate.FilterGroup(0, "AND")).Build("WHERE")}
GROUP BY
    DATE(v.hstamp),
    v.channelV2,
    v.publisher_id,
    v.pub_type,
    v.site_id,
    v.site_type,
    v.size,
    v.carrier_id,
    v.country,
    v.region,
    v.city,
    v.zip,
    v.metrocode,
    v.brand,
    v.model,
    v.marketing_name,
    v.os,
    v.os_version,
    v.device_type,
    v.agegroup_id,
    v.gender_id,
    v.house_income_id,
    v.device_lang,
    v.device_browser,
    v.device_browser_version,
    v.path_hop_count,
    v.media_plcmt,
    v.video_maxduration,
    v.is_ias_ip_fraud,
    v.video_skippable,
    v.supports_banner,
    v.supports_video,
    v.supports_richmedia,
    v.supports_native,
    v.supports_vpaid,
    v.ads_txt,
    v.req_authorized,
    v.supports_audio,
    v.audio_skippable,
    v.hhip_flag,
    v.path_complete,
    v.is_private_pmp_deal )
